arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1977_03.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def print_keys(d, indent=0):
    if isinstance(d, dict):
        for k in list(d.keys())[:20]:
            print(' ' * indent + str(k))
            if isinstance(d[k], dict):
                print_keys(d[k], indent+2)
            elif isinstance(d[k], list) and len(d[k]) > 0 and isinstance(d[k][0], dict):
                print(' ' * (indent+2) + f'list of {len(d[k])} items')

print_keys(data)
"
